    previous.current = value;
    return () => controls.stop();
  }, [value, reduce]);
  return (
    <span
      className={cn("tabular-nums", className)}
      aria-label={value.toFixed(decimals)}
    >
      <span aria-hidden="true">{display.toFixed(decimals)}</span>
    </span>
  );
}

