export function AnimatedTabsIndicator({
  items,
  value,
  defaultValue,
  onValueChange,
  className,
}: {
  items: { value: string; label: string; content: React.ReactNode }[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
