  vec3 color = base * (.13 + diffuse * .66) + vec3(.93, .97, 1.) * specular * .8;
  color += base * fold * .25 + vec3(.7, .83, .94) * rim * .28;
  // Fine longitudinal highlights suggest a surface, without a texture asset.
  color *= .97 + .03 * sin(vUv.y * 210.);
