  speed = 1,
  paused = false,
  imageSrc,
  composition = "fold",
  label = "Interactive WebGL artwork",
}: WebGLProps & { kind: SceneKind }) {
  const colors = {
    particles: "#b9a4f8",
    ribbons: "#8daed1",
    liquid: "#737fd7",
    orb: "#eab89d",
    terrain: "#b2c08b",
    distortion: "#d7dfcf",
  };
  const backgrounds = {
    particles: "#10101c",
    ribbons: "#10151d",
    liquid: "#1c2945",
    orb: "#241c2b",
    terrain: "#14221e",
    distortion: "#d7dfcf",
