    terrain: "#b2c08b",
    distortion: "#d7dfcf",
  };
  const backgrounds = {
    particles: "#10101c",
    ribbons: "#10151d",
    liquid: "#1c2945",
    orb: "#241c2b",
    terrain: "#14221e",
    distortion: "#d7dfcf",
  };
  const color = suppliedColor ?? colors[kind];
  const ref = React.useRef<HTMLDivElement>(null);
