      new THREE.TextureLoader().load(
        imageSrc,
        (t) => {
          if (cancelled) {
            t.dispose();
            return;
          }
          texture.dispose();
          texture = t;
          material.uniforms.picture.value = t;
          material.uniforms.imageAspect.value = t.image.width / t.image.height;
          invalidate();
        },
        undefined,
        () => {
          invalidate();
        },
      );
