  const { size } = useThree();
  const material = React.useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: vertex,
        fragmentShader: fragment,
        side: THREE.DoubleSide,
        uniforms: {
          time: { value: 0 },
          aspect: { value: 1 },
          strand: { value: index },
          orbit: { value: orbit ? 1 : 0 },
