    <div
      className="absolute inset-0 grid place-items-center"
      data-webgl-fallback
    >
      {kind === "ribbons" ? (
        <RibbonPoster color={color} />
      ) : kind === "terrain" ? (
        <svg
          viewBox="0 0 900 400"
          preserveAspectRatio="xMidYMid slice"
          className="h-full w-full"
          aria-hidden="true"
        >
          {Array.from({ length: 34 }, (_, row) => {
            const points = Array.from({ length: 80 }, (_, col) => {
              const x = (col / 79) * 1000 - 50;
              const z = row / 33;
              const h =
                90 * Math.exp(-(((x - 310) / 150) ** 2)) +
                65 * Math.exp(-(((x - 610) / 110) ** 2));
              const y =
                140 +
                z * 230 -
                h * Math.sin(z * Math.PI) * 1.5 +
                Math.sin(x * 0.013 + z * 5) * 12;
              return `${x.toFixed(2)},${y.toFixed(2)}`;
            });
            return (
              <polyline
                key={row}
                points={points.join(" ")}
                fill="none"
                stroke={color}
                strokeWidth={1}
                opacity={0.2 + row / 55}
              />
            );
          })}
        </svg>
      ) : kind === "distortion" && imageSrc ? (
        <img src={imageSrc} alt="" className="h-full w-full object-cover" />
      ) : (
        <svg viewBox="0 0 600 400" className="h-full w-full" aria-hidden="true">
          {kind === "particles" ? (
            Array.from({ length: 700 }, (_, i) => {
              const a = i * 2.399963,
                r = 65 + Math.sqrt(i / 700) * 165;
              return (
                <circle
                  key={i}
                  cx={(300 + Math.cos(a) * r).toFixed(3)}
                  cy={(200 + Math.sin(a) * r * 0.52).toFixed(3)}
                  r={0.5 + (i % 4) * 0.3}
                  fill={color}
                  opacity={0.4 + (i % 6) * 0.1}
                />
              );
            })
          ) : kind === "orb" ? (
            <>
              <defs>
                <radialGradient id="jez-orb-poster" cx="30%" cy="22%">
                  <stop stopColor="#fff4e4" />
                  <stop offset=".35" stopColor={color} />
                  <stop offset=".7" stopColor="#695786" />
                  <stop offset="1" stopColor="#1f2035" />
                </radialGradient>
              </defs>
              <circle cx="300" cy="200" r="128" fill="url(#jez-orb-poster)" />
            </>
          ) : (
            Array.from({ length: 32 }, (_, i) => (
              <path
                key={i}
                d={`M 0 ${70 + i * 9} Q 150 ${-30 + i * 13} 300 ${130 + i * 7} T 600 ${95 + i * 10}`}
                fill="none"
                stroke={color}
                strokeWidth={1.1}
                opacity={0.3 + (i % 5) * 0.13}
              />
            ))
          )}
        </svg>
      )}
    </div>
  );
  return (
    <div
      ref={ref}
      role="img"
      aria-label={label}
      style={{ background: backgrounds[kind] }}
      className={cn(
        "relative h-[400px] w-full overflow-hidden rounded-xl",
        className,
      )}
    >
      {ready && !lost && !reduce && visible ? (
        <Boundary fallback={fallback}>
          <Canvas
            dpr={[1, 1.5]}
            frameloop={paused ? "demand" : "always"}
            camera={{ position: [0, 0, 5], fov: 48 }}
            gl={{ antialias: true, alpha: true, powerPreference: "low-power" }}
            onCreated={({ gl }) => {
              gl.domElement.addEventListener(
                "webglcontextlost",
                () => setLost(true),
                { once: true },
              );
            }}
          >
            <WebGLScene
              kind={kind}
              color={color}
              speed={speed}
              imageSrc={imageSrc}
              composition={composition}
            />
          </Canvas>
        </Boundary>
      ) : (
        fallback
      )}
    </div>
  );
}

"use client";
import * as React from "react";
import { useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";
import { RibbonScene } from "./webgl-ribbons";
import {
  screenVertex,
  orbFragment,
  liquidFragment,
  distortionFragment,
  terrainVertex,
  terrainFragment,
  particleVertex,
  particleFragment,
} from "./webgl-shaders";
export type SceneKind =
  | "particles"
  | "ribbons"
  | "liquid"
  | "orb"
  | "terrain"
  | "distortion";
export type SceneProps = {
  kind: SceneKind;
  color: string;
  speed: number;
  imageSrc?: string;
  composition?: "fold" | "orbit";
