        ref.current.rotation.z,
        -0.16 + pointer.x * 0.08,
        3,
        d,
      );
    }
  });
  return (
    <mesh
      ref={ref}
      material={material}
      rotation={kind === "terrain" ? [-0.58, 0, -0.16] : [0, 0, 0]}
    >
      {kind === "terrain" ? (
        <planeGeometry args={[6.8, 4.2, 220, 160]} />
      ) : (
        <planeGeometry args={[2, 2]} />
