  const [workspace, setWorkspace] = React.useState("");
  const [mode, setMode] = React.useState("Team");
  return (
    <section
      className={cn(
        "grid overflow-hidden rounded-2xl border border-border md:grid-cols-[220px_minmax(0,1fr)]",
