              ? "Name your workspace and choose how you’ll use it."
              : "Here’s the workspace you’ve put together."}
        </p>
        {step < 2 ? (
          <form
            className="grid gap-6"
            onSubmit={(e) => {
              e.preventDefault();
              setStep((s) => s + 1);
            }}
