              </label>
            ) : (
              <>
                <label className="grid gap-2 text-sm font-medium">
                  Workspace name
                  <Input
                    required
                    placeholder="Acme Studio"
                    value={workspace}
                    onChange={(e) => setWorkspace(e.target.value)}
                  />
                </label>
