                        <input
                          className="sr-only peer"
                          type="radio"
                          name="mode"
                          value={value}
                          checked={mode === value}
                          onChange={() => setMode(value)}
                        />
                        {i ? <Users size={20} /> : <UserRound size={20} />}
                        <span className="mt-3 block text-sm font-medium peer-focus-visible:underline">
                          {value}
