              </div>
              <Check className="ml-auto" size={20} />
            </div>
            <p className="mb-6 text-sm text-muted-foreground">
              Your choices are ready in this preview.
            </p>
            <Button variant="outline" onClick={() => setStep(0)}>
              Edit setup
            </Button>
          </>
        )}
      </div>
    </section>
  );
}

