import { Button } from "../ui/button";
export function SignInForm({
  className,
  onSubmit,
}: {
  className?: string;
  onSubmit?: (data: Record<string, string>) => Promise<void>;
}) {
  const [status, setStatus] = React.useState("");
  const [busy, setBusy] = React.useState(false);
  return (
    <form
      className={cn(
