          <motion.span
            key={String(visible)}
            initial={{
              opacity: 0,
              rotate: reduce ? 0 : -35,
              scale: reduce ? 1 : 0.7,
            }}
            animate={{ opacity: 1, rotate: 0, scale: 1 }}
            exit={{
              opacity: 0,
              rotate: reduce ? 0 : 35,
              scale: reduce ? 1 : 0.7,
            }}
            transition={{ duration: reduce ? 0 : 0.12 }}
          >
            {visible ? <EyeOff size={16} /> : <Eye size={16} />}
          </motion.span>
        </AnimatePresence>
      </button>
    </div>
  );
}

